def small():
    return nn.Sequential(nn.Linear(10, 16), nn.ReLU(), nn.Linear(16, 3))


def wide():
    return nn.Sequential(nn.Linear(10, 64), nn.ReLU(), nn.Linear(64, 3))


BUILDERS = {"small": small, "wide": wide}


def build(name):
    return BUILDERS[name]()

def batches(filename, shuffle):
    tensors = torch.load(filename, map_location="cpu", weights_only=True)
    return DataLoader(TensorDataset(tensors["features"], tensors["labels"]),
                      batch_size=32, shuffle=shuffle)

def train_epoch(student, teacher, batches, optimizer, alpha, temperature):
    student.train()
    teacher.eval()
    for features, labels in batches:
        with torch.no_grad():
            teacher_logits = teacher(features)

@torch.no_grad()
def evaluate(student, batches):
    student.eval()
    correct, count = 0, 0
    for features, labels in batches:
        predictions = student(features).argmax(dim=-1)
        correct += (predictions == labels).sum().item()
        count += len(labels)
    return correct / count if count else None
